async function renderAttendance(){
  const isPresident=user.role==='president';
  const isFaculty=user.role==='faculty_coordinator';
  const isCoordinator=user.role==='club_coordinator';
  if(isCoordinator){ await renderODCoordinator(); return; }
  if(!isPresident&&!isFaculty){view.innerHTML=card('Attendance & OD',empty('This section is available to club presidents and their faculty coordinators.'));return;}
  const clubs=await apiRequest('/clubs/my-clubs');
  if(!clubs.length){view.innerHTML=card('Attendance & OD',empty('No clubs are assigned to this account.'));return;}
  let activeClubId=clubs[0]._id;
  const render=async()=>{
    const club=clubs.find(c=>String(c._id)===String(activeClubId));
    const [sessions,ods]=await Promise.all([apiRequest(`/attendance/sessions?club=${activeClubId}`),isPresident?apiRequest(`/attendance/ods?club=${activeClubId}`):Promise.resolve([])]);
    const clubSelect=`<label>Club<select id="attendanceClubSelect">${clubs.map(c=>`<option value="${c._id}" ${String(c._id)===String(activeClubId)?'selected':''}>${escapeHtml(c.name)}</option>`).join('')}</select></label>`;
    const actions=isPresident?`<div class="actions"><button class="primary" id="newAttendanceSession">Create attendance</button><button class="secondary" id="newODList">Create OD list</button></div>`:'';
    const attendanceRows=sessions.length?sessions.map(x=>`<tr><td>${escapeHtml(x.purpose||x.sessionName)}</td><td>${formatDate(x.createdAt)}</td><td>${x.records?.length||0}</td><td>${x.records?.filter(r=>r.present).length||0}</td><td>${x.records?.filter(r=>!r.present).length||0}</td><td><button class="secondary open-attendance-session" data-id="${x._id}">${isPresident?'View / edit':'View'}</button></td></tr>`).join(''):'';
    const odRows=ods.map(x=>`<tr><td>${escapeHtml(x.description)}</td><td>${formatDate(x.createdAt)}</td><td>${x.rows?.length||0}</td><td>${status(x.status)}</td><td><button class="secondary open-od-list" data-id="${x._id}">${isPresident?'View / edit':'View'}</button></td></tr>`).join('');
    view.innerHTML=card('Attendance & OD',`${clubSelect}<div class="section-space">${actions}</div>${card('Attendance records',attendanceRows?`<div class="table-wrap"><table><thead><tr><th>Purpose</th><th>Date confirmed</th><th>Members</th><th>Present</th><th>Absent</th><th>Action</th></tr></thead><tbody>${attendanceRows}</tbody></table></div>`:empty('No attendance has been confirmed yet.'))}${isPresident?card('OD lists',odRows?`<div class="table-wrap"><table><thead><tr><th>Purpose</th><th>Submitted</th><th>Students</th><th>Status</th><th>Action</th></tr></thead><tbody>${odRows}</tbody></table></div>`:empty('No OD lists submitted for this club yet.')):''}`);
    document.getElementById('attendanceClubSelect').onchange=async e=>{activeClubId=e.target.value;await render()};
    document.getElementById('newAttendanceSession')?.addEventListener('click',()=>showStandaloneAttendance(club,null));
    document.getElementById('newODList')?.addEventListener('click',()=>showODForm(club,null));
    view.querySelectorAll('.open-attendance-session').forEach(b=>b.onclick=async()=>{try{const session=await apiRequest(`/attendance/sessions/${b.dataset.id}`);showStandaloneAttendance(club,session)}catch(e){toast(e.message,true)}});
    view.querySelectorAll('.open-od-list').forEach(b=>b.onclick=async()=>{try{const od=await apiRequest(`/attendance/ods/${b.dataset.id}`);showODForm(club,od)}catch(e){toast(e.message,true)}});
  };
  await render();
}

async function showStandaloneAttendance(club,session){
  if(user.role==='faculty_coordinator'){
    if(!session){toast('Attendance record not found.',true);return;}
    const records=session.records||[];
    view.innerHTML=card(`Attendance details · ${escapeHtml(club.name)}`,`<div class="profile-list"><div class="profile-row"><span>Purpose</span><strong>${escapeHtml(session.purpose||session.sessionName||'—')}</strong></div><div class="profile-row"><span>Date confirmed</span><strong>${formatDate(session.confirmedAt||session.createdAt)}</strong></div><div class="profile-row"><span>Confirmed by</span><strong>${escapeHtml(session.takenBy?.name||'—')}</strong></div><div class="profile-row"><span>Total members</span><strong>${records.length}</strong></div><div class="profile-row"><span>Present</span><strong>${records.filter(r=>r.present).length}</strong></div><div class="profile-row"><span>Absent</span><strong>${records.filter(r=>!r.present).length}</strong></div></div><h3>Attendance list</h3>${records.length?`<div class="table-wrap"><table><thead><tr><th>Student</th><th>Email</th><th>Status</th></tr></thead><tbody>${records.map(r=>`<tr><td>${escapeHtml(r.student?.name||'Unknown student')}</td><td>${escapeHtml(r.student?.email||'—')}</td><td>${r.present?'Present':'Absent'}</td></tr>`).join('')}</tbody></table></div>`:empty('No student records in this attendance session.')}<button class="secondary section-space" id="attendanceDetailsBack">Back to attendance records</button>`);
    document.getElementById('attendanceDetailsBack').onclick=()=>renderAttendance();
    return;
  }
  if(user.role!=='president'){toast('You do not have permission to edit attendance.',true);return;}
  const members=club.members||[]; const existing=new Map((session?.records||[]).map(r=>[String(r.student?._id||r.student),!!r.present]));
  view.innerHTML=card(`${session?'Edit attendance':'Create attendance'} · ${escapeHtml(club.name)}`,`<p class="muted">Enter the purpose, mark each club member present or absent, then confirm. Confirmed records are sent to members and are view-only for them and the Faculty Coordinator.</p><form id="standaloneAttendanceForm"><label>Purpose of attendance<input id="attendancePurpose" required maxlength="500" value="${escapeHtml(session?.purpose||'')}" placeholder="e.g. Gaming Club planning meeting"></label><div class="table-wrap section-space"><table><thead><tr><th>Student</th><th>Email</th><th>Club role</th><th>Present</th></tr></thead><tbody>${members.map(m=>{const role=(club.memberRoles||[]).find(r=>String(r.user?._id||r.user)===String(m._id))?.position||m.position||'Member';return `<tr><td>${escapeHtml(m.name)}</td><td>${escapeHtml(m.email)}</td><td>${escapeHtml(role)}</td><td><input type="checkbox" data-attendance-student="${m._id}" ${existing.get(String(m._id))?'checked':''}></td></tr>`}).join('')}</tbody></table></div><div class="form-actions section-space"><button class="primary">${session?'Confirm updated attendance':'Confirm attendance'}</button><button class="secondary" type="button" id="cancelAttendanceForm">Cancel</button></div></form>`);
  document.getElementById('cancelAttendanceForm').onclick=()=>renderAttendance();
  document.getElementById('standaloneAttendanceForm').onsubmit=async e=>{e.preventDefault();const records=[...e.target.querySelectorAll('[data-attendance-student]')].map(x=>({student:x.dataset.attendanceStudent,present:x.checked}));const body={clubId:club._id,purpose:document.getElementById('attendancePurpose').value.trim(),records};try{const url=session?`/attendance/sessions/${session._id}/confirm`:'/attendance/sessions';const result=await apiRequest(url,{method:session?'PUT':'POST',body});toast(result.message);await renderAttendance()}catch(err){toast(err.message,true)}};
}

async function showODForm(club,od){
  if(user.role!=='president'){toast('OD lists are view-only for the Faculty Coordinator.',true);return;}
  const rows=od?.rows?.length?od.rows:[{name:'',email:'',details:''}];
  const rowHtml=(r,i)=>`<div class="card od-row"><div class="form-grid"><label>Student name<input class="od-name" required maxlength="120" value="${escapeHtml(r.name||'')}"></label><label>Student email<input class="od-email" required type="email" value="${escapeHtml(r.email||'')}"></label><label class="full-field">OD details<textarea class="od-details" required maxlength="1000" rows="2">${escapeHtml(r.details||'')}</textarea></label><div class="full-field"><button class="danger remove-od-row" type="button">Remove student</button></div></div></div>`;
  view.innerHTML=card(`${od?'Edit OD list':'Create OD list'} · ${escapeHtml(club.name)}`,`<p class="muted">The full list is sent to the Club Coordinator for approval. Each listed student receives only a notification, not the list.</p><form id="odForm"><label>Purpose / description of OD<input id="odDescription" required maxlength="500" value="${escapeHtml(od?.description||'')}" placeholder="e.g. Inter-college gaming tournament representation"></label><div id="odRows" class="section-space">${rows.map(rowHtml).join('')}</div><div class="actions section-space"><button class="secondary" type="button" id="addODRow">+ Add student</button><button class="primary" type="submit">Confirm and send OD list</button><button class="secondary" type="button" id="cancelODForm">Cancel</button></div></form>`);
  const rowsEl=document.getElementById('odRows');
  const bindRemove=()=>rowsEl.querySelectorAll('.remove-od-row').forEach(b=>b.onclick=()=>{if(rowsEl.querySelectorAll('.od-row').length===1){toast('Keep at least one student row.',true);return;}b.closest('.od-row').remove()});
  bindRemove(); document.getElementById('addODRow').onclick=()=>{rowsEl.insertAdjacentHTML('beforeend',rowHtml({name:'',email:'',details:''},rowsEl.children.length));bindRemove()};
  document.getElementById('cancelODForm').onclick=()=>renderAttendance();
  document.getElementById('odForm').onsubmit=async e=>{e.preventDefault();const body={clubId:club._id,description:document.getElementById('odDescription').value.trim(),rows:[...rowsEl.querySelectorAll('.od-row')].map(r=>({name:r.querySelector('.od-name').value.trim(),email:r.querySelector('.od-email').value.trim(),details:r.querySelector('.od-details').value.trim()}))};try{const url=od?`/attendance/ods/${od._id}`:'/attendance/ods';const result=await apiRequest(url,{method:od?'PUT':'POST',body});toast(result.message);await renderAttendance()}catch(err){toast(err.message,true)}};
}

async function renderODCoordinator(){
  const lists=await apiRequest('/attendance/ods');
  view.innerHTML=card('OD lists for review',lists.length?`<div class="table-wrap"><table><thead><tr><th>Club</th><th>Purpose</th><th>Submitted by</th><th>Date</th><th>Students</th><th>Status</th><th>Action</th></tr></thead><tbody>${lists.map(o=>`<tr><td>${escapeHtml(o.club?.name||'—')}</td><td>${escapeHtml(o.description)}</td><td>${escapeHtml(o.submittedBy?.name||'—')}</td><td>${formatDate(o.createdAt)}</td><td>${o.rows?.length||0}</td><td>${status(o.status)}</td><td><button class="secondary coordinator-view-od" data-id="${o._id}">Open list</button>${o.status==='pending'?` <button class="success coordinator-od-decision" data-id="${o._id}" data-decision="approved">Approve</button> <button class="danger coordinator-od-decision" data-id="${o._id}" data-decision="rejected">Reject</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:empty('No OD lists have been submitted.'));
  view.querySelectorAll('.coordinator-view-od').forEach(b=>b.onclick=async()=>{try{const o=await apiRequest(`/attendance/ods/${b.dataset.id}`);view.innerHTML=card(`OD list · ${escapeHtml(o.description)}`,`<p><strong>Club:</strong> ${escapeHtml(o.club?.name||'—')}</p><p><strong>Status:</strong> ${status(o.status)}</p><div class="table-wrap"><table><thead><tr><th>Student</th><th>Email</th><th>OD details</th></tr></thead><tbody>${o.rows.map(r=>`<tr><td>${escapeHtml(r.name)}</td><td>${escapeHtml(r.email)}</td><td>${escapeHtml(r.details)}</td></tr>`).join('')}</tbody></table></div><button class="secondary" id="backODs">Back to OD lists</button>`);document.getElementById('backODs').onclick=()=>renderAttendance()}catch(e){toast(e.message,true)}});
  view.querySelectorAll('.coordinator-od-decision').forEach(b=>b.onclick=()=>{const row=b.closest('tr');let box=row.querySelector('.inline-decision');if(box){box.remove();return;}box=document.createElement('div');box.className='inline-decision';box.innerHTML='<label>Decision note<textarea rows="2" maxlength="1000"></textarea></label><button type="button" class="primary confirm-inline-decision">Confirm</button><button type="button" class="secondary cancel-inline-decision">Cancel</button>';b.closest('td').appendChild(box);box.querySelector('.cancel-inline-decision').onclick=()=>box.remove();box.querySelector('.confirm-inline-decision').onclick=async()=>{try{const r=await apiRequest(`/attendance/ods/${b.dataset.id}/decision`,{method:'PATCH',body:{decision:b.dataset.decision,note:box.querySelector('textarea').value}});toast(r.message);await renderODCoordinator()}catch(e){toast(e.message,true)}}});
}

async function renderBudgets(){
  const filter=user.club?`?club=${user.club}`:''; const budgets=await apiRequest('/budgets'+filter); let form='';
  if(['president','vice_president'].includes(user.role)){const events=await apiRequest(`/events?club=${user.club}`);form=card('Propose a budget',`<form id="budgetForm" class="form-grid"><label>Event<select id="budgetEvent" required>${events.map(e=>`<option value="${e._id}">${escapeHtml(e.title)}</option>`).join('')}</select></label><label>Amount<input id="budgetAmount" type="number" min="0" step="0.01" required placeholder="5000" /></label><label class="full-field">Justification<textarea id="budgetJustification" rows="3" placeholder="Explain the expected expenses"></textarea></label><div class="full-field form-actions"><button class="primary">Submit budget proposal</button></div></form>`)}
   // keeps rendering consistent
  view.innerHTML=form+card('Budgets',budgets.length?`<div class="table-wrap"><table><thead><tr><th>Club</th><th>Event</th><th>Amount</th><th>Proposed by</th><th>Status</th><th>Action</th></tr></thead><tbody>${budgets.map(b=>`<tr><td>${escapeHtml(b.club?.name||'—')}</td><td>${escapeHtml(b.event?.title||'—')}</td><td>₹${Number(b.proposedAmount||0).toLocaleString()}</td><td>${escapeHtml(b.proposedBy?.name||'—')}</td><td>${status(b.status)}</td><td>${user.role==='club_coordinator'&&b.status==='pending'?`<div class="actions"><button class="success decide-budget" data-id="${b._id}" data-decision="approved">Approve</button><button class="danger decide-budget" data-id="${b._id}" data-decision="rejected">Reject</button></div>`:'—'}</td></tr>`).join('')}</tbody></table></div>`:empty('No budget records found.'));
  const f=document.getElementById('budgetForm'); if(f)f.onsubmit=async(e)=>{e.preventDefault();try{await apiRequest('/budgets',{method:'POST',body:{event:budgetEvent.value,club:user.club,proposedAmount:Number(budgetAmount.value),justification:budgetJustification.value}});toast('Budget proposal submitted');await renderBudgets()}catch(err){toast(err.message,true)}};
  view.querySelectorAll('.decide-budget').forEach(b=>b.onclick=()=>{const row=b.closest('tr');let box=row.querySelector('.inline-decision');if(box){box.remove();return;}box=document.createElement('div');box.className='inline-decision';box.innerHTML='<label>Decision note<textarea rows="2" maxlength="1000"></textarea></label><button type="button" class="primary confirm-inline-decision">Confirm</button><button type="button" class="secondary cancel-inline-decision">Cancel</button>';b.closest('td').appendChild(box);box.querySelector('.cancel-inline-decision').onclick=()=>box.remove();box.querySelector('.confirm-inline-decision').onclick=async()=>{try{await apiRequest(`/budgets/${b.dataset.id}/decision`,{method:'PATCH',body:{decision:b.dataset.decision,note:box.querySelector('textarea').value}});toast('Budget decision saved');await renderBudgets()}catch(e){toast(e.message,true)}}});
}

async function renderJoiningReview(){const reqs=await apiRequest('/joining-requests/pending');view.innerHTML=card('Pending club joining requests',reqs.length?`<div class="table-wrap"><table><thead><tr><th>Student</th><th>Email</th><th>Club</th><th>Submitted</th><th>Details</th><th>Action</th></tr></thead><tbody>${reqs.map(r=>`<tr><td>${escapeHtml(r.student?.name||'—')}</td><td>${escapeHtml(r.student?.email||'—')}</td><td>${escapeHtml(r.club?.name||'—')}</td><td>${formatDate(r.createdAt)}</td><td><button class="secondary joining-request-details" data-id="${r._id}">View details</button></td><td><div class="actions"><button class="success decide-join" data-id="${r._id}" data-decision="approved">Approve</button><button class="danger decide-join" data-id="${r._id}" data-decision="rejected">Reject</button></div></td></tr>`).join('')}</tbody></table></div>`:empty('No pending club joining requests.'));
  view.querySelectorAll('.joining-request-details').forEach(b=>b.onclick=()=>{const r=reqs.find(x=>String(x._id)===String(b.dataset.id));if(!r)return;view.innerHTML=card(`Joining request · ${escapeHtml(r.student?.name||'Student')}`,`<div class="profile-list"><div class="profile-row"><span>Email</span><strong>${escapeHtml(r.student?.email||'—')}</strong></div><div class="profile-row"><span>Club</span><strong>${escapeHtml(r.club?.name||'—')}</strong></div><div class="profile-row"><span>Submitted</span><strong>${formatDate(r.createdAt)}</strong></div></div><h3>Why the student wants to join</h3><p>${escapeHtml(r.motivation||'No explanation provided.')}</p><h3>Role preferences</h3><ol>${(r.roleChoices||[]).map(x=>`<li>${escapeHtml(x)}</li>`).join('')||'<li>No role preferences recorded.</li>'}</ol><button class="secondary" id="backJoiningRequests">Back to requests</button>`);document.getElementById('backJoiningRequests').onclick=()=>renderJoiningReview()});
  view.querySelectorAll('.decide-join').forEach(b=>b.onclick=()=>{const row=b.closest('tr');let box=row.querySelector('.inline-join-decision');if(box){box.remove();return;}const decision=b.dataset.decision;box=document.createElement('div');box.className='inline-join-decision';box.innerHTML='<label>Decision note<textarea rows="2" maxlength="1000"></textarea></label><button type="button" class="primary confirm-join-decision">Confirm decision</button><button type="button" class="secondary cancel-join-decision">Cancel</button>';b.closest('td').appendChild(box);box.querySelector('.cancel-join-decision').onclick=()=>box.remove();box.querySelector('.confirm-join-decision').onclick=async()=>{try{await apiRequest(`/joining-requests/${b.dataset.id}/decision`,{method:'PATCH',body:{decision,note:box.querySelector('textarea').value}});toast('Joining request updated');await renderJoiningReview()}catch(e){toast(e.message,true)}}});
}

async function renderVenueReview(){
  const pending=await apiRequest('/venues/requests/pending');
  view.innerHTML=card('Pending venue requests',pending.length?`<div class="table-wrap"><table><thead><tr><th>Event</th><th>Club</th><th>Requested venue</th><th>Date & time</th><th>Budget</th><th>Details / decision</th></tr></thead><tbody>${pending.map(e=>`<tr><td><strong>${escapeHtml(e.title)}</strong><br><small class="muted">${escapeHtml(e.eventType||'solo')} event</small></td><td>${escapeHtml(e.club?.name||'—')}</td><td>${escapeHtml(e.venue?.name||'—')}<br><small class="muted">${escapeHtml(e.venue?.location||'')}</small></td><td>${formatDate(e.date)}<br>${escapeHtml(e.expectedStartTime||'—')} – ${escapeHtml(e.expectedEndTime||'—')}</td><td>₹${Number(e.proposedBudget||0).toLocaleString()}</td><td><div class="actions"><button class="secondary venue-event-details" data-id="${e._id}">View full details</button><button class="primary venue-review-open" data-id="${e._id}">Review request</button></div><div id="venue-detail-${e._id}" class="section-space"></div><div id="venue-decision-${e._id}" class="section-space"></div></td></tr>`).join('')}</tbody></table></div>`:empty('No pending venue requests.'));
  const escapeAttr = (v) => escapeHtml(String(v ?? ''));
  view.querySelectorAll('.venue-event-details').forEach(b=>b.onclick=async()=>{
    const slot=document.getElementById(`venue-detail-${b.dataset.id}`);
    if(slot.innerHTML){slot.innerHTML='';b.textContent='View full details';return;}
    try{
      const e=await apiRequest(`/events/${b.dataset.id}`);
      slot.innerHTML=card('Event details',`<div class="profile-list"><div class="profile-row"><span>Event</span><strong>${escapeHtml(e.title)}</strong></div><div class="profile-row"><span>Club</span><strong>${escapeHtml(e.club?.name||'—')}</strong></div><div class="profile-row"><span>Submitted by</span><strong>${escapeHtml(e.createdBy?.name||'—')} · ${escapeHtml(e.createdBy?.email||'')}</strong></div><div class="profile-row"><span>Date</span><strong>${formatDate(e.date)}</strong></div><div class="profile-row"><span>Expected time</span><strong>${escapeHtml(e.expectedStartTime||'—')} – ${escapeHtml(e.expectedEndTime||'—')}</strong></div><div class="profile-row"><span>Requested venues</span><strong>${escapeHtml((e.requestedVenues||[e.venue]).map(v=>v?.name).filter(Boolean).join(', ')||'—')}</strong></div><div class="profile-row"><span>Proposed budget</span><strong>₹${Number(e.proposedBudget||0).toLocaleString()}</strong></div><div class="profile-row"><span>Event type</span><strong>${escapeHtml(e.eventType||'solo')}</strong></div><div class="profile-row"><span>Club Coordinator decision</span><strong>${escapeHtml(e.coordinatorStatus||'pending')}</strong></div></div><h3>Description</h3><p>${escapeHtml(e.description||'No description provided.')}</p><h3>Requirements</h3><p>${escapeHtml(e.requirements||'None provided.')}</p>`);
      b.textContent='Hide details';
    }catch(err){toast(err.message,true)}
  });
  view.querySelectorAll('.venue-review-open').forEach(b=>b.onclick=()=>{
    const event=pending.find(e=>String(e._id)===String(b.dataset.id)); if(!event)return;
    const slot=document.getElementById(`venue-decision-${b.dataset.id}`);
    if(slot.innerHTML){slot.innerHTML='';b.textContent='Review request';return;}
    slot.innerHTML=card('Review venue request',`<form class="venue-decision-form" data-id="${event._id}"><label>Decision<select name="decision" required><option value="">Choose a decision</option><option value="approved">Approve requested venue</option><option value="rejected">Reject requested venue</option></select></label><label class="full-field">Decision note / reason<textarea name="note" rows="3" maxlength="1500" placeholder="Explain the decision, if needed"></textarea></label><div class="full-field venue-alternatives hidden"><strong>Select available alternative venues to send to the Club President and Faculty Coordinator</strong><p class="muted">Only venues shown as available for this event date are listed. Select any alternatives that can be used.</p>${(event.availableVenues||[]).filter(v=>String(v._id)!==String(event.venue?._id||event.venue)).map(v=>`<label class="checkbox-field"><input type="checkbox" name="alternativeVenueIds" value="${escapeAttr(v._id)}"> ${escapeHtml(v.name)}${v.location?` — ${escapeHtml(v.location)}`:''}</label>`).join('')||'<p class="muted">No available alternative venues were found for this date.</p>'}</div><div class="full-field form-actions"><button class="primary" type="submit">Confirm decision</button><button class="secondary venue-decision-cancel" type="button">Cancel</button></div></form>`);
    b.textContent='Close review';
    const form=slot.querySelector('.venue-decision-form');
    const decisionSelect=form.elements.decision;
    const alternativesWrap=form.querySelector('.venue-alternatives');
    decisionSelect.onchange=()=>alternativesWrap.classList.toggle('hidden',decisionSelect.value!=='rejected');
    form.querySelector('.venue-decision-cancel').onclick=()=>{slot.innerHTML='';b.textContent='Review request';};
    form.onsubmit=async(ev)=>{
      ev.preventDefault();
      const decision=decisionSelect.value;
      if(!['approved','rejected'].includes(decision)){toast('Choose Approve or Reject first.',true);return;}
      const alternativeVenueIds=[...form.querySelectorAll('input[name="alternativeVenueIds"]:checked')].map(x=>x.value);
      if(decision==='rejected' && !form.elements.note.value.trim()){toast('Please enter a reason for rejecting the venue request.',true);return;}
      const submit=form.querySelector('button[type="submit"]'); submit.disabled=true;
      try{
        await apiRequest(`/venues/${event._id}/decision`,{method:'PATCH',body:{decision,note:form.elements.note.value,alternativeVenueIds}});
        toast(`Venue request ${decision}`); await renderVenueReview();
      }catch(err){toast(err.message,true);submit.disabled=false;}
    };
  });
}


async function renderMentees(){const ms=await apiRequest('/mentors/mentees');view.innerHTML=card('My mentees',ms.length?`<div class="table-wrap"><table><thead><tr><th>Student</th><th>Club</th><th>Position</th><th>Events attended</th><th>OD eligible</th><th>Details</th></tr></thead><tbody>${ms.map((m,i)=>`<tr><td>${escapeHtml(m.name)}<br><small class="muted">${escapeHtml(m.email)}</small></td><td>${escapeHtml(m.club||'—')}</td><td>${escapeHtml(m.position||'—')}</td><td>${m.eventsAttended}</td><td>${m.odEligibleEvents}</td><td><button class="secondary mentee-detail" data-index="${i}">View clubs & activity</button></td></tr>`).join('')}</tbody></table></div>`:empty('No mentees assigned.'));view.querySelectorAll('.mentee-detail').forEach(b=>b.onclick=()=>{const m=ms[Number(b.dataset.index)];view.innerHTML=card(m.name,`<p class="muted">${escapeHtml(m.email)} · ${escapeHtml(m.position||'Member')}</p>${card('Club memberships',m.clubs?.length?`<div class="table-wrap"><table><thead><tr><th>Club</th><th>Role</th></tr></thead><tbody>${m.clubs.map(c=>`<tr><td>${escapeHtml(c.name)}</td><td>${escapeHtml(c.position||'Member')}</td></tr>`).join('')}</tbody></table></div>`:empty('No club memberships recorded.'))}${card('Event participation',m.eventParticipation?.length?`<div class="table-wrap"><table><thead><tr><th>Event</th><th>Date</th><th>Organizing club</th><th>Venue</th><th>Participation</th><th>Event role</th><th>Registration</th></tr></thead><tbody>${m.eventParticipation.map(a=>`<tr><td>${escapeHtml(a.event)}${a.collaboratingClubs?.length?`<br><small class="muted">With ${escapeHtml(a.collaboratingClubs.join(', '))}</small>`:''}</td><td>${formatDate(a.date)}</td><td>${escapeHtml(a.club||'—')}</td><td>${escapeHtml(a.venue||'—')}</td><td>${escapeHtml(a.participationType||'Registered participant')}</td><td>${escapeHtml(a.eventRole||'Participant')}</td><td>${escapeHtml(a.registrationStatus||'—')}</td></tr>`).join('')}</tbody></table></div>`:empty('No event registrations or confirmed event roles recorded.'))}${card('Attendance and OD history',m.participation?.length?`<div class="table-wrap"><table><thead><tr><th>Record type</th><th>Purpose / event</th><th>Date</th><th>Club</th><th>Attendance</th><th>OD status</th><th>Details</th></tr></thead><tbody>${m.participation.map(a=>`<tr><td>${escapeHtml(a.type||'Event attendance')}</td><td>${escapeHtml(a.event||'—')}</td><td>${formatDate(a.date)}</td><td>${escapeHtml(a.club||'—')}</td><td>${a.present===null||a.present===undefined?'—':(a.present?'Present':'Absent')}</td><td>${escapeHtml(a.odStatus||(a.odEligible?'Approved':'—'))}</td><td>${escapeHtml([a.purpose,a.decisionNote].filter(Boolean).join(' · ')||'—')}</td></tr>`).join('')}</tbody></table></div>`:empty('No attendance or OD records found for this mentee.'))}`)});}

async function renderNotifications(){
 const ns=await apiRequest('/notifications');
 view.innerHTML=card('Notifications',`<div class="card-head"><div class="actions">${ns.some(n=>!n.read)?'<button id="readAll" class="secondary">Mark all read</button>':''}<button id="deleteReadNotifications" class="secondary">Delete read</button><button id="deleteAllNotifications" class="danger">Delete all</button></div></div>`+(ns.length?`<div class="notification-list">${ns.map(n=>`<article class="notification ${n.read?'':'unread'}" data-notification="${n._id}" tabindex="0" role="button"><div class="notification-top"><strong>${escapeHtml(n.title)}</strong><div class="actions"><button class="danger delete-notification" data-id="${n._id}" aria-label="Delete notification">Delete</button></div></div><small>${formatDate(n.createdAt)} ${n.read?'':'• unread'}</small><div class="notification-content hidden"><p>${escapeHtml(n.message)}</p></div><small class="muted">Click to open and mark as read</small></article>`).join('')}</div>`:empty('No notifications.')));
 document.getElementById('readAll')?.addEventListener('click',async()=>{await apiRequest('/notifications/read-all',{method:'PATCH'});toast('All notifications marked as read');await renderNotifications();updateNotifCount()});
 document.getElementById('deleteReadNotifications')?.addEventListener('click',async()=>{if(!confirm('Delete all read notifications?'))return;await apiRequest('/notifications/read',{method:'DELETE'});toast('Read notifications deleted');await renderNotifications();updateNotifCount()});
 document.getElementById('deleteAllNotifications')?.addEventListener('click',async()=>{if(!confirm('Delete all your notifications?'))return;await apiRequest('/notifications',{method:'DELETE'});toast('All notifications deleted');await renderNotifications();updateNotifCount()});
 view.querySelectorAll('.notification').forEach(el=>{const open=async()=>{el.querySelector('.notification-content')?.classList.toggle('hidden');if(el.classList.contains('unread')){await apiRequest(`/notifications/${el.dataset.notification}/read`,{method:'PATCH'});el.classList.remove('unread');updateNotifCount()}};el.addEventListener('click',e=>{if(e.target.closest('.delete-notification'))return;open()});el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();open()}})});
 view.querySelectorAll('.delete-notification').forEach(b=>b.onclick=async(e)=>{e.stopPropagation();await apiRequest(`/notifications/${b.dataset.id}`,{method:'DELETE'});await renderNotifications();updateNotifCount()});
}

async function renderMessages(){
 const [messages,users]=await Promise.all([apiRequest('/messages'),apiRequest('/auth/directory').catch(()=>[])]);
 const allowed={student:['president','vice_president','club_coordinator','faculty_mentor'],president:['student','vice_president','faculty_coordinator','club_coordinator','venue_admin','faculty_mentor'],vice_president:['student','president','faculty_coordinator','club_coordinator','venue_admin','faculty_mentor'],faculty_coordinator:['president','vice_president','club_coordinator','venue_admin'],club_coordinator:['president','vice_president','faculty_coordinator','venue_admin'],venue_admin:['president','vice_president','faculty_coordinator','club_coordinator'],faculty_mentor:['student'],director:['student','faculty_mentor','club_coordinator','faculty_coordinator','venue_admin','president','vice_president']};
 const recipients=users.filter(u=>(allowed[user.role]||[]).includes(u.role));
 const form=card('Send a message',`<form id="messageForm" class="form-grid"><label>Recipient email<input id="msgTo" list="recipientOptions" placeholder="president1@college.edu" required/><datalist id="recipientOptions">${recipients.map(u=>`<option value="${escapeHtml(u.email)}">${escapeHtml(u.name)} (${escapeHtml(u.role)})</option>`).join('')}</datalist></label><label>Subject<input id="msgSubject" required maxlength="140" placeholder="Event coordination"/></label><label class="full-field">Message<textarea id="msgBody" required rows="4" placeholder="Write your message"></textarea></label><div class="full-field form-actions"><button class="primary">Send message</button></div></form>`);
 const list=messages.length?`<div class="notification-list">${messages.map(m=>{const incoming=String(m.recipient?._id)===String(user._id);return `<article class="notification ${incoming&&!m.readAt?'unread':''}"><div class="notification-top"><strong>${escapeHtml(m.subject)}</strong><small>${formatDate(m.createdAt)}</small></div><p class="muted">${incoming?'From':'To'}: ${escapeHtml(incoming?m.sender?.email:m.recipient?.email||'')}</p><p>${escapeHtml(m.body)}</p>${incoming&&!m.readAt?`<button class="secondary read-message" data-id="${m._id}">Mark read</button>`:''}<button class="secondary reply-message" data-email="${escapeHtml(incoming?m.sender?.email:m.recipient?.email||'')}" data-subject="${escapeHtml('Re: '+m.subject)}" data-body="${escapeHtml(m.body)}">Reply</button></article>`}).join('')}</div>`:empty('No messages yet.');
 view.innerHTML=form+card('Inbox and sent messages',list);
 document.getElementById('messageForm').onsubmit=async e=>{e.preventDefault();try{await apiRequest('/messages',{method:'POST',body:{to:msgTo.value,subject:msgSubject.value,body:msgBody.value}});toast('Message sent');await renderMessages()}catch(err){toast(err.message,true)}};
 view.querySelectorAll('.read-message').forEach(b=>b.onclick=async()=>{await apiRequest(`/messages/${b.dataset.id}/read`,{method:'PATCH'});await renderMessages()});
 view.querySelectorAll('.reply-message').forEach(b=>b.onclick=()=>{msgTo.value=b.dataset.email;msgSubject.value=b.dataset.subject;msgBody.value=`\n\n--- Previous message ---\n${b.dataset.body}`;msgBody.focus()});
}
async function renderAccounts(){
 const canCreate=user.role==='system_admin';
 const isDirector=user.role==='director';
 const canManageAccounts=canCreate||isDirector;
 if(!canManageAccounts){view.innerHTML=empty('You do not have access to account administration.');return;}
 const accounts=await apiRequest('/auth/accounts');
 const mentors=accounts.filter(a=>a.role==='faculty_mentor'&&a.isActive);
 const students=accounts.filter(a=>['student','president','vice_president'].includes(a.role)&&a.isActive);
 const unassigned=students.filter(a=>!a.assignedMentor);
 const roleName={student:'Student',president:'Club President',vice_president:'Vice President',faculty_coordinator:'Faculty Coordinator',faculty_mentor:'Mentor',club_coordinator:'Club Coordinator',venue_admin:'Venue Administrator',director:'Director',system_admin:'Account Administrator'};
 let creation='';
 if(canCreate){
  const roles=[['student','Student'],['faculty_mentor','Mentor'],['president','Club President'],['faculty_coordinator','Faculty Coordinator']];
  creation=card('Create accounts',`<p class="muted">Enter the name and email for each account. Accounts are saved to MongoDB and remain available after server restarts.</p><form id="accountForm" class="form-grid"><label>Account type<select id="accountRole">${roles.map(r=>`<option value="${r[0]}">${r[1]}</option>`).join('')}</select></label><label>How many accounts?<input id="accountCount" type="number" min="1" max="100" value="1" required/></label><label>Start numbering at<input id="accountStart" type="number" min="1" value="1" required/></label><label>Temporary password<input id="accountPassword" type="password" minlength="8" required autocomplete="new-password" placeholder="Enter a temporary password"/></label><div id="accountHolderFields" class="full-field"></div><div class="full-field muted">Enter a name and email for every account. Example: Rahul Kumar · rahul@college.edu. Existing emails are skipped and reported.</div><div class="full-field form-actions"><button class="primary" type="submit">Create accounts</button></div></form><div id="accountResults"></div>`);
 }
 const assignment=user.role==='director'?card('Assign mentors',`<p class="muted">${unassigned.length} student(s) currently have no mentor. Choose a mentor and enter student email addresses separated by commas or new lines.</p><form id="assignMenteesForm" class="form-grid"><label>Mentor<select id="assignMentorEmail" required><option value="">Select a mentor</option>${mentors.map(m=>`<option value="${escapeHtml(m.email)}">${escapeHtml(m.name)} · ${escapeHtml(m.email)}</option>`).join('')}</select></label><label class="full-field">Student emails<textarea id="assignStudentEmails" required rows="3" placeholder="${unassigned.slice(0,5).map(s=>s.email).join(', ')}"></textarea></label><div class="full-field form-actions"><button class="primary" type="submit" ${mentors.length?'':'disabled'}>Save mentor assignments</button></div></form>`):'';
 view.innerHTML=creation+assignment+card(canCreate?'Saved accounts':'Student directory',`<div class="actions" style="margin-bottom:12px"><button class="secondary" id="refreshAccounts" type="button">Refresh list</button></div><p class="muted">${accounts.filter(a=>a.role==='student').length} student(s) · ${accounts.length} total accounts currently saved in the database.</p><div class="table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Club</th><th>Mentor</th><th>Status</th>${canManageAccounts?'<th>Actions</th>':''}</tr></thead><tbody>${accounts.map(a=>{const studentRole=['student','president','vice_president'].includes(a.role);return `<tr><td>${escapeHtml(a.name)}</td><td>${escapeHtml(a.email)}</td><td>${escapeHtml(roleName[a.role]||a.role)}</td><td>${escapeHtml(a.club||'—')}</td><td>${escapeHtml(a.assignedMentor?.email||'Not assigned')}</td><td>${a.isActive?'Active':'Inactive'}</td>${canManageAccounts?`<td><div class="actions">${(canCreate||(isDirector&&studentRole))?`<button class="secondary edit-account" data-id="${a._id}" data-name="${escapeHtml(a.name)}" data-email="${escapeHtml(a.email)}" data-role="${a.role}" data-position="${escapeHtml(a.position||'')}">Edit</button>`:''}${isDirector&&studentRole?`<select class="mentor-select" data-id="${a._id}" aria-label="Mentor for ${escapeHtml(a.name)}"><option value="">No mentor</option>${mentors.map(m=>`<option value="${m._id}" ${String(a.assignedMentor?._id||'')===String(m._id)?'selected':''}>${escapeHtml(m.name)} (${escapeHtml(m.email)})</option>`).join('')}</select><button class="secondary save-account-mentor" data-id="${a._id}">Save mentor</button>`:''}${(canCreate||(isDirector&&studentRole))?`<button class="danger delete-account" data-id="${a._id}" data-name="${escapeHtml(a.name)}">Delete</button>`:''}</div></td>`:''}</tr>`}).join('')}</tbody></table></div>`);
 document.getElementById('refreshAccounts').onclick=()=>renderAccounts();
 view.querySelectorAll('.edit-account').forEach(b=>b.onclick=async()=>{const a=accounts.find(x=>String(x._id)===String(b.dataset.id));if(!a)return;view.innerHTML=card('Edit Student Account',`<p class="muted">Edit the existing account details. The student identity and mentor assignment remain separate from club-specific roles.</p><form id="editAccountForm" class="form-grid"><label>Full name<input id="editAccountName" required maxlength="120" value="${escapeHtml(a.name)}"></label><label>Email address<input id="editAccountEmail" required type="email" maxlength="254" value="${escapeHtml(a.email)}"></label><label>Position / title<input id="editAccountPosition" value="${escapeHtml(a.position||'')}"></label>${canCreate?`<label>Role<select id="editAccountRole">${['student','president','vice_president','faculty_coordinator','faculty_mentor','club_coordinator','venue_admin','director','system_admin'].map(r=>`<option value="${r}" ${a.role===r?'selected':''}>${escapeHtml(roleName[r]||r)}</option>`).join('')}</select></label><label>Account status<select id="editAccountStatus"><option value="active" ${a.isActive?'selected':''}>Active</option><option value="inactive" ${!a.isActive?'selected':''}>Inactive</option></select></label><label class="full-field">New password (leave blank to keep current)<input id="editAccountPassword" type="password" minlength="8" autocomplete="new-password"></label>`:''}<div class="full-field form-actions"><button class="primary" type="submit">Save changes</button><button class="secondary" id="cancelEditAccount" type="button">Cancel</button></div></form>`);document.getElementById('cancelEditAccount').onclick=()=>renderAccounts();document.getElementById('editAccountForm').onsubmit=async e=>{e.preventDefault();const body={name:document.getElementById('editAccountName').value.trim(),email:document.getElementById('editAccountEmail').value.trim(),position:document.getElementById('editAccountPosition').value};if(canCreate){body.role=document.getElementById('editAccountRole').value;body.isActive=document.getElementById('editAccountStatus').value==='active';const password=document.getElementById('editAccountPassword').value;if(password)body.password=password;}try{await apiRequest(`/auth/accounts/${a._id}`,{method:'PATCH',body});toast('Account updated');await renderAccounts()}catch(err){toast(err.message,true)}}});

 view.querySelectorAll('.save-account-mentor').forEach(b=>b.onclick=async()=>{const select=view.querySelector(`.mentor-select[data-id="${b.dataset.id}"]`);try{const result=await apiRequest(`/auth/accounts/${b.dataset.id}/mentor`,{method:'PATCH',body:{mentorId:select.value||null}});toast(result.message);await renderAccounts()}catch(e){toast(e.message,true)}});
 view.querySelectorAll('.delete-account').forEach(b=>b.onclick=async()=>{if(!confirm(`Permanently delete ${b.dataset.name}'s account? Related club and mentor links will be cleaned up.`))return;try{await apiRequest(`/auth/accounts/${b.dataset.id}`,{method:'DELETE'});toast('Account deleted');await renderAccounts()}catch(e){toast(e.message,true)}});
 if(user.role==='director') document.getElementById('assignMenteesForm').onsubmit=async e=>{e.preventDefault();const mentorEmail=document.getElementById('assignMentorEmail').value;const studentEmails=document.getElementById('assignStudentEmails').value.split(/[\n,;]+/).map(x=>x.trim()).filter(Boolean);try{const result=await apiRequest('/auth/assign-mentees',{method:'POST',body:{mentorEmail,studentEmails}});toast(`Assigned ${result.assigned.length} student(s)`);await renderAccounts()}catch(err){toast(err.message,true)}};
 if(canCreate){
  const holderFields=document.getElementById('accountHolderFields');
  const roleSelect=document.getElementById('accountRole'), countInput=document.getElementById('accountCount'), startInput=document.getElementById('accountStart');
  const accountPrefix=role=>({student:'student',faculty_mentor:'mentor',president:'president',faculty_coordinator:'coordinator'}[role]||role);
  const accountLabel=role=>({student:'Student',faculty_mentor:'Mentor',president:'Club President',faculty_coordinator:'Faculty Coordinator'}[role]||'Account');
  const renderHolderFields=()=>{let count=Math.max(1,Math.min(100,Number(countInput.value)||1)), start=Math.max(1,Number(startInput.value)||1), role=roleSelect.value, prefix=accountPrefix(role), label=accountLabel(role);holderFields.innerHTML=`<h3>Account holder details</h3><div class="account-holder-grid">${Array.from({length:count},(_,idx)=>{let num=start+idx;return `<div class="account-holder-row"><strong>${label} ${idx+1}</strong><label>Account holder name<input class="account-name" data-index="${idx}" required maxlength="120" placeholder="Enter full name" value=""/></label><label>Email address<input class="account-email" data-index="${idx}" type="email" required maxlength="254" placeholder="name@college.edu" value="${prefix}${num}@college.edu"/></label></div>`}).join('')}</div>`;};
  roleSelect.addEventListener('change',renderHolderFields);countInput.addEventListener('input',renderHolderFields);startInput.addEventListener('input',renderHolderFields);renderHolderFields();
  document.getElementById('accountForm').onsubmit=async e=>{e.preventDefault();const role=roleSelect.value,count=Number(countInput.value),start=Number(startInput.value),password=document.getElementById('accountPassword').value;const names=[...document.querySelectorAll('.account-name')],emails=[...document.querySelectorAll('.account-email')];const accounts=names.map((el,i)=>({name:el.value.trim(),email:emails[i].value.trim()}));if(accounts.some(a=>!a.name||!a.email)){toast('Enter a name and email for every account',true);return;}try{const result=await apiRequest('/auth/bulk-create',{method:'POST',body:{role,count,start,password,accounts}});const out=document.getElementById('accountResults');out.innerHTML=card('Creation result',`<p>${result.created.length} account(s) created. ${result.skipped.length} email(s) skipped.</p>${result.created.length?`<div class="table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Temporary password</th></tr></thead><tbody>${result.created.map(a=>`<tr><td>${escapeHtml(a.name)}</td><td>${escapeHtml(a.email)}</td><td>${escapeHtml(a.password)}</td></tr>`).join('')}</tbody></table></div>`:''}${result.skipped.length?`<p class="muted">Skipped (already registered): ${result.skipped.map(escapeHtml).join(', ')}</p>`:''}`);toast(`Created ${result.created.length}; skipped ${result.skipped.length}`);const resultHtml=out.innerHTML;await renderAccounts();const fresh=document.getElementById('accountResults');if(fresh)fresh.innerHTML=resultHtml}catch(err){toast(err.message,true)}};
 }
}

