// Add a show/hide control to every password field, including forms rendered later.
function addPasswordVisibilityControls(root=document) {
 root.querySelectorAll('input[type="password"]').forEach(input => {
  if (input.dataset.visibilityReady) return; input.dataset.visibilityReady='1';
  const button=document.createElement('button'); button.type='button'; button.className='secondary password-toggle'; button.textContent='Show password'; button.style.marginTop='6px'; button.style.fontSize='12px';
  button.addEventListener('click',()=>{const visible=input.type==='text';input.type=visible?'password':'text';button.textContent=visible?'Show password':'Hide password';});
  input.insertAdjacentElement('afterend',button);
 });
}
const passwordObserver=new MutationObserver(()=>addPasswordVisibilityControls(document));
passwordObserver.observe(document.body,{childList:true,subtree:true});
addPasswordVisibilityControls(document);
